import java.util.*;
import java.io.*;

public class Main {
    static final int SIZE = (1 << 21) + 1;
    static char[] ibuf = new char[SIZE];
    static int ibufPos = 0, ibufLen = 0;
    static char[] obuf = new char[SIZE];
    static int oPos = 0;
    static final int N = 250005;
    static final int K = 19;
    static int[][] f = new int[N][K];
    static int n, k, M;
    static int[] factorials = new int[N];
    static int[] invFactorials = new int[N];

    static int readInt() throws IOException {
        int x = 0;
        int sign = 1;
        int ch;
        while (true) {
            ch = getc();
            if (ch == -1) throw new EOFException();
            if (!Character.isWhitespace(ch)) break;
        }
        if (ch == '-') {
            sign = -1;
            ch = getc();
        }
        do {
            x = x * 10 + (ch - '0');
            ch = getc();
        } while (Character.isDigit(ch));
        return x * sign;
    }

    static void writeInt(int x) throws IOException {
        if (x == 0) {
            putc('0');
            return;
        }
        if (x < 0) {
            putc('-');
            x = -x;
        }
        int top = 0;
        char[] stk = new char[20];
        while (x > 0) {
            stk[top++] = (char) ('0' + x % 10);
            x /= 10;
        }
        for (int i = top - 1; i >= 0; i--) {
            putc(stk[i]);
        }
    }

    static int getc() throws IOException {
        if (ibufPos == ibufLen) {
            ibufLen = System.in.read(ibuf);
            ibufPos = 0;
            if (ibufLen == -1) return -1;
        }
        return ibuf[ibufPos++];
    }

    static void putc(char x) throws IOException {
        obuf[oPos++] = x;
        if (oPos == SIZE) flush();
    }

    static void flush() throws IOException {
        System.out.write(obuf, 0, oPos);
        oPos = 0;
    }

    static int add(int x, int y) {
        int res = x + y;
        if (res >= M) res -= M;
        return res;
    }

    static int add(int x, int y, int... args) {
        int res = add(x, y);
        for (int arg : args) {
            res = add(res, arg);
        }
        return res;
    }

    static int sub(int x, int y) {
        int res = x - y;
        if (res < 0) res += M;
        return res;
    }

    static int mul(int x, int y) {
        return (int)((long) x * y % M);
    }

    static int mul(int x, int y, int... args) {
        int res = mul(x, y);
        for (int arg : args) {
            res = mul(res, arg);
        }
        return res;
    }

    static void inc(int[] x, int y) {
        x[0] += y;
        if (x[0] >= M) x[0] -= M;
    }

    static void dec(int[] x, int y) {
        x[0] -= y;
        if (x[0] < 0) x[0] += M;
    }

    static int power(int x, int y) {
        int res = 1;
        int base = x;
        int exp = y;
        while (exp > 0) {
            if ((exp & 1) == 1) res = mul(res, base);
            base = mul(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int inv(int x) {
        return power(x, M - 2);
    }

    static void prepareFactorials(int n) {
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = mul(factorials[i - 1], i);
        }
        invFactorials[n] = inv(factorials[n]);
        for (int i = n - 1; i >= 0; i--) {
            invFactorials[i] = mul(invFactorials[i + 1], i + 1);
        }
    }

    static int recursiveProcess(int s, int c) {
        if (s == 0) return 1;
        if (c == k) return 0;
        int[] resRef = {f[s][c]};
        if (resRef[0] != -1) return resRef[0];
        int res = 0;
        int hb = 1;
        while (hb <= s) hb <<= 1;
        hb >>= 1;
        for (int t = s; t != -1; --t) {
            t &= s;
            if ((t & hb) == 0) return res;
            int temp = mul(invFactorials[t], k - c, recursiveProcess(s ^ t, c + 1));
            res = add(res, temp);
        }
        f[s][c] = res;
        return res;
    }

    public static void main(String[] args) throws IOException {
        Arrays.fill(f, -1);
        n = readInt();
        k = readInt();
        M = readInt();
        prepareFactorials(n);
        if ((n & 1) == 1) {
            writeInt(power(k, n));
            putc('\n');
            flush();
            return;
        }
        int result = sub(power(k, n), mul(factorials[n], recursiveProcess(n, 0)));
        writeInt(result);
        putc('\n');
        flush();
    }
}
